'use strict';
const API='/api', input=document.querySelector('#merge-files'), list=document.querySelector('#merge-tracks');
const upload=document.querySelector('#upload-tracks'), merge=document.querySelector('#merge-button'), error=document.querySelector('#merge-error');
let tracks=[], csrf='', epoch=0;
async function request(route,options={}){const h=new Headers(options.headers||{});if(options.method&&options.method!=='GET'&&csrf)h.set('X-CSRF-Token',csrf);const r=await fetch(API+route,{...options,headers:h,credentials:'same-origin',cache:'no-store'});const j=await r.json();if(!r.ok)throw Object.assign(new Error(j.error||'Request failed'),{status:r.status});return j}
async function post(route,data){return request(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})}
function size(n){return (n/1000000).toFixed(1)+' MB'}
function render(){list.replaceChildren();tracks.forEach((t,i)=>{const row=document.createElement('div');row.className='merge-track';const order=document.createElement('b');order.className='merge-order';order.textContent=String(i+1).padStart(2,'0');const info=document.createElement('div');info.className='merge-track-info';const name=document.createElement('strong');name.textContent=t.file.name;const meta=document.createElement('span');meta.textContent=size(t.file.size)+(t.uploaded?' · Uploaded':'');info.append(name,meta);const actions=document.createElement('div');actions.className='merge-actions';[['↑',-1],['↓',1]].forEach(([label,delta])=>{const b=document.createElement('button');b.textContent=label;b.disabled=i+delta<0||i+delta>=tracks.length||tracks.some(x=>x.uploaded);b.onclick=()=>{[tracks[i],tracks[i+delta]]=[tracks[i+delta],tracks[i]];render()};actions.append(b)});const del=document.createElement('button');del.textContent='Remove';del.className='remove';del.disabled=tracks.some(x=>x.uploaded);del.onclick=()=>{tracks.splice(i,1);render()};actions.append(del);row.append(order,info,actions);list.append(row)});document.querySelector('#track-summary').textContent=tracks.length?tracks.length+' Tracks · '+size(tracks.reduce((a,t)=>a+t.file.size,0)):'ยังไม่ได้เลือกเพลง';upload.disabled=tracks.length<2||tracks.some(t=>t.uploaded);merge.disabled=tracks.length<2||tracks.some(t=>!t.uploaded)}
function addFiles(files){for(const file of files){const ext=(file.name.split('.').pop()||'').toLowerCase();if(!['wav','flac','m4a'].includes(ext)||file.size<=0||file.size>2000*1000*1000)continue;if(tracks.length<50)tracks.push({file,uploaded:false,id:null})}render()}
input.onchange=()=>{addFiles(input.files);input.value=''};
const drop=document.querySelector('#merge-drop');drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();addFiles(e.dataTransfer.files)};
async function uploadOne(t,index){const init=await post('/upload/init',{name:t.file.name,size:t.file.size});let sent=0,n=0;while(sent<t.file.size){const end=Math.min(sent+init.chunkSize,t.file.size),r=await request('/upload/chunk',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Upload-Id':init.uploadId,'X-Chunk-Index':String(n)},body:t.file.slice(sent,end)});sent=end;n++;document.querySelector('#upload-status').textContent='Uploading '+(index+1)+' / '+tracks.length+' · '+Math.floor(sent/t.file.size*100)+'%'}const done=await post('/upload/complete',{uploadId:init.uploadId});t.id=done.fileId;t.uploaded=true}
upload.onclick=async()=>{upload.disabled=true;error.hidden=true;try{for(let i=0;i<tracks.length;i++){if(!tracks[i].uploaded)await uploadOne(tracks[i],i)}document.querySelector('#upload-status').textContent='UPLOAD COMPLETE · '+tracks.length+' Tracks พร้อม Merge';render()}catch(e){error.hidden=false;error.textContent='Upload failed · '+e.message;render()}};
async function waitJob(job){for(;;){document.querySelector('#merge-status').textContent=job.status==='queued'?'WAITING IN QUEUE · '+job.position:'MERGING…';if(job.status==='succeeded')return job.result;if(job.status==='failed')throw new Error(job.error);await new Promise(r=>setTimeout(r,2000));job=await request('/jobs/'+job.jobId)}}
merge.onclick=async()=>{merge.disabled=true;error.hidden=true;const my=++epoch;try{let job=await post('/merge',{fileIds:tracks.map(t=>t.id),format:document.querySelector('#merge-format').value,name:document.querySelector('#album-name').value.trim(),requestId:crypto.randomUUID()});const out=await waitJob(job);if(my!==epoch)return;const f=out.files[0],box=document.querySelector('#merge-download');box.replaceChildren();const a=document.createElement('a');a.href=API+'/download/'+encodeURIComponent(out.jobId)+'/'+encodeURIComponent(f.name);a.target='_blank';a.rel='noopener';a.textContent='Download '+f.name+' · '+size(f.size);box.append(a);document.querySelector('#merge-status').textContent='MERGE COMPLETE · '+out.tracks+' Tracks · ไฟล์หมดอายุหลัง 59 นาที'}catch(e){error.hidden=false;error.textContent='Merge failed · '+e.message}finally{merge.disabled=false}};
(async()=>{try{const me=await request('/auth/me');csrf=me.csrf;document.querySelector('#account-name').textContent=me.user.username;document.querySelector('#auth-gate').hidden=true;document.querySelector('#merge-workspace').hidden=me.user.mustChange;if(me.user.mustChange)throw new Error('กรุณาตั้งรหัสผ่านใหม่ที่หน้า Split Audio ก่อน')}catch(e){document.querySelector('#auth-status').textContent=e.message||'กรุณาเข้าสู่ระบบก่อน';document.querySelector('#login-link').hidden=false}})();